package com.surgepotiontimer;

import net.runelite.api.Client;
import net.runelite.client.ui.overlay.infobox.InfoBox;

import javax.inject.Inject;
import java.awt.Color;
import net.runelite.client.ui.overlay.infobox.InfoBoxPriority;

public class SurgePotionInfoBox extends InfoBox
{

	private final SurgePotionTimerPlugin plugin;
	private final SurgePotionTimerConfig config;

	@Inject
	public SurgePotionInfoBox(Client client, SurgePotionTimerPlugin plugin, SurgePotionTimerConfig config)
	{
		super(null, plugin);
		this.plugin = plugin;
		this.config = config;
		setPriority(InfoBoxPriority.MED);
	}

	@Override
	public String getText()
	{
		String str;
		if (config.surgePotionMode() == SurgePotionMode.TICKS)
		{
			str = String.valueOf(plugin.surgePotionInTicks);
		}
		else if (config.surgePotionMode() == SurgePotionMode.DECIMALS)
		{
			str = SurgePotionTimerPlugin.to_mmss_precise_short(plugin.surgePotionInTicks);
		}
		else
		{
			str = SurgePotionTimerPlugin.to_mmss(plugin.surgePotionInTicks);
		}
		return str;
	}

	@Override
	public Color getTextColor()
	{
		if (plugin.surgePotionInTicks < 25)
		{
			return Color.RED;
		}
		return Color.WHITE;
	}

	@Override
	public boolean render()
	{
		return plugin.surgePotioned;
	}

	@Override
	public String getTooltip()
	{
		return "Surge potion";
	}
}

package com.surgepotiontimer;

public enum SurgePotionMode
{
	TICKS,
	SECONDS,
	DECIMALS
}

package com.surgepotiontimer;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("surgepotiontimer")
public interface SurgePotionTimerConfig extends Config
{
	@ConfigItem(
		keyName = "surgePotionMode",
		name = "Display mode",
		description = "Configures how the surge potion timer is displayed.",
		position = 1
	)
	default SurgePotionMode surgePotionMode()
	{
		return SurgePotionMode.SECONDS;
	}
}

package com.surgepotiontimer;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;

@Slf4j
@PluginDescriptor(
	name = "Surge Potion Timer",
	description = "Better surge potion timer, accounts for world lag and accurate in ToB",
	tags = {"surge", "potion", "timer", "better", "accurate", "tob"}
)
public class SurgePotionTimerPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private SurgePotionTimerConfig config;

	@Inject
	private InfoBoxManager infoBoxManager;

	@Inject
	private ItemManager itemManager;

	private SurgePotionInfoBox infoBox;

	boolean surgePotioned;
	int surgePotionInTicks = -1;
	int prevSurgePotionCycles = 0;

	@Override
	protected void startUp() throws Exception
	{
		infoBox = new SurgePotionInfoBox(client, this, config);
		infoBox.setImage(itemManager.getImage(ItemID._4DOSESURGE));
		infoBoxManager.addInfoBox(infoBox);
	}

	@Override
	protected void shutDown() throws Exception
	{
		surgePotioned = false;
		surgePotionInTicks = -1;
		prevSurgePotionCycles = 0;
		infoBoxManager.removeInfoBox(infoBox);
		infoBox = null;
	}

	@Provides
	SurgePotionTimerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SurgePotionTimerConfig.class);
	}

	@Subscribe
	public void onGameTick(GameTick gameTick)
	{
		final int surgePotionCycles = client.getVarbitValue(VarbitID.SURGE_POTION_TIMER);
		if (surgePotionCycles > 0)
		{
			surgePotioned = true;
			if (surgePotionCycles != prevSurgePotionCycles)
			{
				prevSurgePotionCycles = surgePotionCycles;
				surgePotionInTicks = surgePotionCycles * 10;
			}

			final boolean tobActive = client.getVarbitValue(6440) > 1;
			final boolean tobRoomActive = client.getVarbitValue(6447) > 0;
			if (!tobActive || tobRoomActive)
			{
				--surgePotionInTicks;
			}
		}
		else
		{
			surgePotioned = false;
			prevSurgePotionCycles = 0;
		}
	}

	public static String to_mmss(int ticks)
	{
		int m = ticks / 100;
		int s = (ticks - m * 100) * 6 / 10;
		return m + (s < 10 ? ":0" : ":") + s;
	}

	public static String to_mmss_precise_short(int ticks)
	{
		int min = ticks / 100;
		int tmp = (ticks - min * 100) * 6;
		int sec = tmp / 10;
		int sec_tenth = tmp - sec * 10;
		return min + (sec < 10 ? ":0" : ":") + sec + "." +
				sec_tenth;
	}
}

package com.surgepotiontimer;

import com.surgepotiontimer.SurgePotionTimerPlugin;
import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class ExamplePluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(SurgePotionTimerPlugin.class);
		RuneLite.main(args);
	}
}
